/**
 * Exo SYR2K driver: mirrors PolyBench/C syr2k.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"

/* Include the Exo-generated kernel header. */
#include "generated/syr2k/syr2k.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++) {
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
      B[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i*j+3)%n) / m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline SYR2K kernel, written in a clear way first.
@proc
def kernel_syr2k_unoptimized(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
    B: DATA_TYPE[n, m] @ DRAM,
):
    # Sizes are non-negative; full matrices are used (no interior slicing).
    assert n >= 0
    assert m >= 0

    for i in seq(0, n):
        # Scale the lower-triangular part of row i.
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

        # Rank-2 update:
        #   C[i,j] += alpha * A[i,k] * B[j,k] + alpha * B[i,k] * A[j,k]
        #
        # Hoist all factors that do not depend on j out of the innermost loop
        # so that alpha*A[i,k] and alpha*B[i,k] are computed only once per (i,k).
        for k in seq(0, m):
            a_ik: DATA_TYPE
            b_ik: DATA_TYPE
            alpha_a_ik: DATA_TYPE
            alpha_b_ik: DATA_TYPE

            a_ik = A[i, k]
            b_ik = B[i, k]
            alpha_a_ik = alpha * a_ik
            alpha_b_ik = alpha * b_ik

            for j in seq(0, i + 1):
                C[i, j] += A[j, k] * alpha_b_ik + B[j, k] * alpha_a_ik

# ---------------------------------------------------------------------------
# Scheduling / optimization
# ---------------------------------------------------------------------------

kernel_syr2k_sched = kernel_syr2k_unoptimized

# 1) Strip-mine the inner j loops by a factor of 4 to make them
#    more amenable to unrolling / vectorization. The bound is (i+1),
#    so we keep a guarded tail.
kernel_syr2k_sched = divide_loop(
    kernel_syr2k_sched, "j #0", 4, ("jo", "ji"), tail="guard"
)
kernel_syr2k_sched = divide_loop(
    kernel_syr2k_sched, "j #0", 4, ("jo2", "ji2"), tail="guard"
)

# 2) Parallelize the outer i loop. Each i-iteration updates a disjoint
#    set of C[i, 0..i], and A/B are read-only, so this is safe.
i_loop = kernel_syr2k_sched.find_loop("i")
kernel_syr2k_sched = parallelize_loop(kernel_syr2k_sched, i_loop)

# 3) Clean up the IR after transformations.
kernel_syr2k_sched = simplify(kernel_syr2k_sched)

# Expose the optimized version under the expected public name.
kernel_syr2k = kernel_syr2k_sched
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_syr2k (/*ctxt=*/NULL, n, m,
		(DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
		(DATA_TYPE*)POLYBENCH_ARRAY(C),
		(DATA_TYPE*)POLYBENCH_ARRAY(A),
		(DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}

